(function(){
 const CART_KEY='zwconnect-cart-v3',ORDERS_KEY='zwconnect-customer-orders-v3';
 let namespace='guest';
 function scoped(key){return`${key}:${namespace}`}
 function migrateLegacy(){if(!localStorage.getItem(scoped(CART_KEY))&&localStorage.getItem('zwconnect-cart-v2'))localStorage.setItem(scoped(CART_KEY),localStorage.getItem('zwconnect-cart-v2'));if(!localStorage.getItem(scoped(ORDERS_KEY))&&localStorage.getItem('zwconnect-customer-orders-v2'))localStorage.setItem(scoped(ORDERS_KEY),localStorage.getItem('zwconnect-customer-orders-v2'))}
 migrateLegacy();
 let cart=load(scoped(CART_KEY),{shopId:null,items:[]}),orders=load(scoped(ORDERS_KEY),[]),trackerLocation=null,loadingOwnerOrders=false,lastOwnerLoad=0;
 function load(key,fallback){try{return JSON.parse(localStorage.getItem(key)||'null')||fallback}catch{return fallback}}
 function save(){localStorage.setItem(scoped(CART_KEY),JSON.stringify(cart));localStorage.setItem(scoped(ORDERS_KEY),JSON.stringify(orders));updateCount()}
 function setCustomerIdentity(userId){save();namespace=userId?`user-${userId}`:'guest';cart=load(scoped(CART_KEY),{shopId:null,items:[]});orders=load(scoped(ORDERS_KEY),[]);updateCount();window.dispatchEvent(new CustomEvent('zwconnect:cart-identity-change',{detail:{namespace}}))}
 function shop(){return shops.find(s=>s.id===cart.shopId)}
 function product(item){return shop()?.products.find(p=>p.sku===item.sku)}
 function itemPrice(item){const p=product(item);return item.saleUnit==='case'?p?.casePrice||0:p?.price||0}
 function itemBase(item){const p=product(item);return item.quantity*(item.saleUnit==='case'?p?.caseSize||1:1)}
 function total(){return cart.items.reduce((sum,item)=>sum+itemPrice(item)*item.quantity,0)}
 function updateCount(){const count=document.querySelector('#cartCount');if(count)count.textContent=cart.items.reduce((n,x)=>n+x.quantity,0)}
 function enhanceProducts(){document.querySelectorAll('.product-card').forEach(card=>{const stock=card.querySelector('.stock-state')?.textContent?.trim();if(stock==='Out of stock'){card.remove();return}const button=card.querySelector('.product-pay');if(button){button.innerHTML='<i data-lucide="shopping-bag"></i> Add to cart';button.classList.add('add-cart-ready')}});window.lucide?.createIcons()}
 function add(shopId,sku){const targetShop=shops.find(s=>s.id===shopId),p=targetShop?.products.find(x=>x.sku===sku);if(!p||p.quantity<=0)return showToast('This product is currently unavailable','package-x');if(cart.shopId&&cart.shopId!==shopId&&!confirm('Your cart contains products from another shop. Clear it and start a new order?'))return;if(cart.shopId!==shopId)cart={shopId,items:[]};const existing=cart.items.find(x=>x.sku===sku);if(existing)existing.quantity+=1;else cart.items.push({sku,quantity:1,saleUnit:targetShop.salesMode==='wholesale'?'case':'unit'});validate();save();showToast(`${p.name} added to cart`,'shopping-bag')}
 function validate(){const target=shop();if(!target){cart={shopId:null,items:[]};return}cart.items=cart.items.filter(item=>{const p=product(item);if(!p||p.quantity<=0)return false;const max=Math.floor(p.quantity/(item.saleUnit==='case'?p.caseSize:1));item.quantity=Math.max(1,Math.min(item.quantity,max));return max>0})}
 function renderCart(){validate();save();const target=shop(),host=document.querySelector('#cartItems');document.querySelector('#cartShopName').textContent=target?`${target.name} • live stock checked before payment`:'Choose products from one shop per order.';host.innerHTML=cart.items.length?cart.items.map((item,index)=>{const p=product(item),maxUnit=p.quantity,maxCase=Math.floor(p.quantity/p.caseSize);return `<article class="cart-row"><span>${p.emoji}</span><div><strong>${p.name}</strong><small>${p.sku} • ${p.quantity} units currently available</small><div class="cart-controls"><select data-cart-unit="${index}">${target.salesMode!=='wholesale'?'<option value="unit">Singular unit</option>':''}${target.salesMode!=='retail'?`<option value="case" ${item.saleUnit==='case'?'selected':''}>Case of ${p.caseSize}</option>`:''}</select><input data-cart-qty="${index}" type="number" min="1" max="${item.saleUnit==='case'?maxCase:maxUnit}" value="${item.quantity}"><button data-cart-remove="${index}"><i data-lucide="trash-2"></i></button></div></div><b>US$ ${(itemPrice(item)*item.quantity).toFixed(2)}</b></article>`}).join(''):'<div class="cart-empty"><i data-lucide="shopping-bag"></i><strong>Your cart is empty</strong><p>Unavailable products are hidden automatically.</p></div>';document.querySelector('#cartTotal').textContent=`US$ ${total().toFixed(2)}`;document.querySelector('#cartCheckoutButton').disabled=!cart.items.length;openModal('cartModal');window.lucide?.createIcons()}
 function openCheckoutUnlocked(){validate();if(!cart.items.length)return;const target=shop(),methods=paymentMethodsFor(target);if(!methods.length)return showToast('This shop has not enabled a payment method yet','wallet-cards');document.querySelector('#cartPaymentMethod').innerHTML=methods.map(m=>`<option value="${m.id}">${m.name} — ${m.account} • ${m.number}</option>`).join('');document.querySelector('#checkoutPaymentDetails').innerHTML=methods.map(m=>`<article><i data-lucide="${m.type==='bank_transfer'?'landmark':'smartphone'}"></i><div><strong>${m.name}</strong><span>${m.account}</span><b>${m.number}</b><small>${m.instructions||''}</small></div></article>`).join('');document.querySelector('#cartCheckoutTotal').textContent=`US$ ${total().toFixed(2)}`;const current=window.ZWCustomer?.current(),form=document.querySelector('#cartCheckoutForm');if(current?.profile){form.elements.name.value=current.profile.display_name||'';form.elements.phone.value=current.profile.phone||''}if(current?.user)form.elements.email.value=current.user.email||'';closeModal('cartModal');openModal('cartCheckoutModal');window.lucide?.createIcons()}
 async function openCheckout(){validate();if(!cart.items.length)return;const account=await window.ZWCustomer?.requireAccount('checkout');if(account)openCheckoutUnlocked()}
 async function submitCheckout(form){validate();const d=new FormData(form),image=d.get('proofImage'),proofText=String(d.get('proofText')||'').trim();if((!(image instanceof File)||!image.size)&&!proofText)return showToast('Upload a payment image or enter proof text','file-warning');if(image?.size>5*1024*1024)return showToast('Payment proof image must be 5 MB or smaller','file-warning');const orderId=crypto.randomUUID(),token=crypto.randomUUID(),target=shop(),items=cart.items.map(item=>({sku:item.sku,quantity:item.quantity,sale_unit:item.saleUnit,base_quantity:itemBase(item)})),summary=cart.items.map(item=>`${item.quantity} ${item.saleUnit} ${product(item).name}`).join(', '),record={id:orderId,token,shopId:target.id,shopName:target.name,customer:d.get('name'),phone:d.get('phone'),reference:d.get('reference'),proofText,hasProofImage:!!image?.size,amount:Number(total().toFixed(2)),status:'payment_submitted',note:'Waiting for the shop to review your payment proof.',items:summary,cartItems:items,submittedAt:new Date().toISOString(),delivery:null};orders.unshift(record);await window.ZWOffline.enqueue('cart_order.submit',{shopId:databaseShopId(target),localShopId:target.id,trackingToken:token,customerName:d.get('name'),phone:d.get('phone'),email:d.get('email')||'',paymentMethodId:d.get('paymentMethod'),reference:d.get('reference'),proofText,proofImage:image?.size?image:null,items},{id:orderId,role:'public'});cart={shopId:null,items:[]};save();form.reset();closeModal('cartCheckoutModal');showReceipt(record)}
 function showReceipt(order){document.querySelector('#orderLookupForm [name="orderId"]').value=order.id;document.querySelector('#orderLookupForm [name="token"]').value=order.token;renderTracker(order);openModal('orderTrackerModal')}
 function statusLabel(status){return({payment_submitted:'Payment proof under review',payment_confirmed:'Purchase confirmed',payment_rejected:'Payment needs attention',delivery_requested:'Waiting for courier offers',courier_selected:'Courier selected',dispatched:'Out for delivery',completed:'Completed'})[status]||status.replaceAll('_',' ')}
 function demoBids(order){if(order.delivery?.bids?.length)return order.delivery.bids;return [{id:'bid-a',courier:'Swift Pedals Harare',phone:'077 310 4421',offered_fee:4.10,minimum_fee:4.10,note:'I can collect in about 20 minutes.',courier_to_pickup_km:2.3,pickup_to_dropoff_km:4.8,pickup_eta_minutes:10,status:'pending'},{id:'bid-b',courier:'Harare Cycle Express',phone:'071 889 2004',offered_fee:5.00,minimum_fee:4.25,note:'Priority pickup with insulated parcel bag.',courier_to_pickup_km:1.1,pickup_to_dropoff_km:4.8,pickup_eta_minutes:5,status:'pending'}]}
 function renderTracker(order){const host=document.querySelector('#orderTrackerContent'),confirmed=['payment_confirmed','delivery_requested','courier_selected','dispatched','completed'].includes(order.status);let delivery='';if(order.status==='payment_confirmed')delivery=`<section class="tracker-action"><h3>Request bike delivery</h3><p>Your purchase is confirmed. Delivery is optional and starts only when you request it.</p><form id="deliveryRequestForm"><input name="address" required placeholder="Delivery address"><textarea name="parcel" placeholder="Delivery notes, landmarks or handling details"></textarea><div class="location-confirm"><button type="button" data-use-dropoff><i data-lucide="locate-fixed"></i> Use my current location</button><span id="dropoffLocationLabel">Location not set</span></div><button class="primary-button">Publish to available couriers</button></form></section>`;if(['delivery_requested','courier_selected','dispatched'].includes(order.status)){const bids=demoBids(order);delivery=`<section class="tracker-action"><h3>${order.status==='courier_selected'?'Selected courier':'Courier offers'}</h3><p>Compare collection time, distance, fare and the courier's note. You control the final selection.</p><div class="bid-list">${bids.map(b=>`<article class="bid-card ${b.status==='accepted'?'selected':''}"><div><span class="status-pill ${b.status==='accepted'?'approved':''}">${b.status}</span><h4>${b.courier}</h4><small>${b.courier_to_pickup_km} km to shop • about ${b.pickup_eta_minutes||Math.max(1,Math.ceil(Number(b.courier_to_pickup_km)/15*60))} min to collection • ${b.pickup_to_dropoff_km} km delivery route</small><p>${b.note||'No additional note'}</p></div><strong>US$ ${Number(b.offered_fee).toFixed(2)}</strong><div>${b.status==='pending'?`<button data-accept-bid="${b.id}">Choose courier</button><button class="reject" data-decline-bid="${b.id}">Decline</button>`:`<a href="tel:${b.phone.replace(/\s/g,'')}">${b.phone}</a>`}</div></article>`).join('')}</div></section>`}host.innerHTML=`<div class="tracker-status"><span><i data-lucide="${confirmed?'badge-check':'clock-3'}"></i></span><div><small>ORDER ${order.id.slice(0,8).toUpperCase()}</small><h3>${statusLabel(order.status)}</h3><p>${order.note||order.confirmation_note||'Status will update when the shop responds.'}</p></div><strong>US$ ${Number(order.amount).toFixed(2)}</strong></div><div class="order-timeline"><span class="done">Proof sent</span><span class="${confirmed?'done':''}">Shop confirmed</span><span class="${order.status==='delivery_requested'||order.status==='courier_selected'?'done':''}">Delivery requested</span><span class="${order.status==='courier_selected'?'done':''}">Courier selected</span></div>${delivery}`;host.dataset.orderId=order.id;window.lucide?.createIcons()}
 async function lookup(form){const d=Object.fromEntries(new FormData(form));let order=orders.find(o=>o.id===d.orderId&&o.token===d.token);if(window.zwconnectSupabase&&navigator.onLine){const {data}=await window.zwconnectSupabase.rpc('get_customer_order',{order_uuid:d.orderId,tracking_uuid:d.token});if(data){order={...order,...data,token:d.token};const i=orders.findIndex(o=>o.id===order.id);if(i>=0)orders[i]=order;else orders.unshift(order);save()}}if(!order)return showToast('Order or private tracking code not found','search-x');renderTracker(order)}
 async function requestDelivery(form){const order=orders.find(o=>o.id===document.querySelector('#orderTrackerContent').dataset.orderId);if(!trackerLocation)return showToast('Use your current location before publishing delivery','map-pin');const d=Object.fromEntries(new FormData(form));order.status='delivery_requested';order.note='Your delivery request is visible to available subscribed couriers.';order.delivery={address:d.address,lat:trackerLocation.lat,lng:trackerLocation.lng,parcel:d.parcel,bids:demoBids({})};save();await window.ZWOffline.enqueue('delivery.request',{orderId:order.id,trackingToken:order.token,address:d.address,latitude:trackerLocation.lat,longitude:trackerLocation.lng,parcel:d.parcel},{role:'public'});renderTracker(order);showToast('Delivery request published to available couriers','bike')}
 async function decideBid(id,accept){const order=orders.find(o=>o.id===document.querySelector('#orderTrackerContent').dataset.orderId),bids=demoBids(order),bid=bids.find(b=>b.id===id);if(!bid)return;if(accept){bids.forEach(b=>b.status=b.id===id?'accepted':'declined');order.status='courier_selected';order.note=`${bid.courier} was selected for US$ ${Number(bid.offered_fee).toFixed(2)}.`}else bid.status='declined';order.delivery={...(order.delivery||{}),bids};save();await window.ZWOffline.enqueue('delivery_bid.decide',{orderId:order.id,trackingToken:order.token,bidId:id,accept},{role:'public'});renderTracker(order)}
 async function refreshServerOrders(){if(loadingOwnerOrders||!window.zwconnectSupabase||!navigator.onLine||Date.now()-lastOwnerLoad<10000)return;loadingOwnerOrders=true;lastOwnerLoad=Date.now();try{const shopId=databaseShopId(shops[0]),{data,error}=await window.zwconnectSupabase.from('customer_orders').select('id,customer_name,customer_phone,payment_reference,payment_proof_path,payment_proof_text,amount,status,submitted_at,customer_order_items(sku,sale_unit,package_quantity,base_quantity)').eq('shop_id',shopId).eq('status','payment_submitted').order('submitted_at',{ascending:false});if(error)throw error;for(const row of data||[]){const mapped={id:row.id,shopId:shops[0].id,customer:row.customer_name,phone:row.customer_phone,reference:row.payment_reference,proofPath:row.payment_proof_path,proofText:row.payment_proof_text,hasProofImage:!!row.payment_proof_path,amount:Number(row.amount),status:row.status,submittedAt:row.submitted_at,items:(row.customer_order_items||[]).map(i=>`${i.package_quantity} ${i.sale_unit} ${i.sku}`).join(', '),cartItems:(row.customer_order_items||[]).map(i=>({sku:i.sku,base_quantity:Number(i.base_quantity)})),server:true},index=orders.findIndex(o=>o.id===row.id);if(index>=0)orders[index]={...orders[index],...mapped};else orders.push(mapped)}save()}catch(error){showToast(error.message||'Could not refresh shop orders','cloud-off')}finally{loadingOwnerOrders=false;if(state.portalTab==='confirmations'||state.portalTab==='orders')window.ZWCart.renderOwnerConfirmations()}}
 function ownerConfirm(id,approve){const payment=customerPayments.find(p=>p.id===id),order=orders.find(o=>o.id===id),note=prompt(approve?'Confirmation note visible to customer':'Reason visible to customer',approve?'Payment received. Your order is packed and ready.':'We could not match this payment reference. Please contact the shop.');if(!note)return;const target=payment||order,localShopId=order?.shopId||'shop-1',items=order?.cartItems||(payment?[{sku:payment.sku,base_quantity:payment.baseQuantity}]:[]);if(target){target.status=approve?'payment_confirmed':'payment_rejected';target.note=note;target.confirmation_note=note}if(approve)for(const item of items)applyLocalMovement(localShopId,item.sku,-Number(item.base_quantity||0));save();window.ZWOffline.enqueue('customer_order.review',{orderId:id,approve,note,localShopId,items,sku:payment?.sku,baseQuantity:payment?.baseQuantity||0},{role:state.portalRole==='worker'?'worker':'shop_owner'});showToast(approve?'Purchase confirmed and ledger posted':'Payment proof rejected without stock movement',approve?'book-check':'x-circle');renderPaymentConfirmations()}
 window.ZWCart={setCustomerIdentity,renderOwnerConfirmations(){refreshServerOrders();const pending=[...customerPayments,...orders].filter(p=>p.status==='pending'||p.status==='payment_submitted');document.querySelector('#portalContent').innerHTML=`<div class="metric-grid">${metric('clock-3','Awaiting proof review',pending.length)}${metric('image','Image or text proof','Required')}${metric('package-check','Stock movement','After approval')}${metric('message-square-text','Customer notes','Required')}</div><section class="portal-panel"><div class="panel-head"><div><h2>Payment proof review</h2><p>Owners and authorised shop workers can confirm with a customer-visible note.</p></div><span class="status-pill">${pending.length} waiting</span></div><div class="portal-table-wrap"><table class="portal-table"><thead><tr><th>Customer</th><th>Cart / parcel</th><th>Proof</th><th>Amount</th><th>Decision</th></tr></thead><tbody>${pending.map(p=>`<tr><td><strong>${p.customer||'Online customer'}</strong><small>${p.phone||p.id.slice(0,8)}</small></td><td>${p.items||`${p.quantity} ${p.unit} • ${p.product}`}</td><td><code>${p.proofText||p.reference||'Image attached'}</code>${p.hasProofImage?`<button data-view-proof="${p.id}">View image</button>`:''}</td><td><strong>US$ ${Number(p.amount).toFixed(2)}</strong></td><td><button data-cart-confirm="${p.id}">Confirm with note</button><button class="reject" data-cart-reject="${p.id}">Reject</button></td></tr>`).join('')||'<tr><td colspan="5">No proofs are waiting.</td></tr>'}</tbody></table></div></section>`;window.lucide?.createIcons()},ownerConfirm};
 document.addEventListener('click',e=>{const pay=e.target.closest('.product-pay');if(pay){e.preventDefault();e.stopImmediatePropagation();add(pay.dataset.payShop,pay.dataset.payProduct)}},true);
 document.addEventListener('DOMContentLoaded',()=>{updateCount();enhanceProducts();new MutationObserver(enhanceProducts).observe(document.querySelector('#shopDetail'),{childList:true,subtree:true});document.querySelector('#cartButton').addEventListener('click',renderCart);document.querySelector('#trackOrderButton').addEventListener('click',()=>openModal('orderTrackerModal'));document.querySelector('#cartCheckoutButton').addEventListener('click',openCheckout);document.addEventListener('click',async e=>{const remove=e.target.closest('[data-cart-remove]');if(remove){cart.items.splice(Number(remove.dataset.cartRemove),1);renderCart()}const proof=e.target.closest('[data-view-proof]');if(proof){const order=orders.find(o=>o.id===proof.dataset.viewProof);if(order?.proofPath&&window.zwconnectSupabase&&navigator.onLine){const {data,error}=await window.zwconnectSupabase.storage.from('payment-proofs').createSignedUrl(order.proofPath,60);if(error)showToast(error.message,'image');else window.open(data.signedUrl,'_blank','noopener')}else{const action=(await window.ZWOffline.list()).find(x=>x.id===proof.dataset.viewProof),file=action?.payload?.proofImage;if(file){const url=URL.createObjectURL(file);window.open(url,'_blank','noopener');setTimeout(()=>URL.revokeObjectURL(url),60000)}else showToast('Payment proof image is unavailable on this device','image')}}const confirm=e.target.closest('[data-cart-confirm]');if(confirm)ownerConfirm(confirm.dataset.cartConfirm,true);const reject=e.target.closest('[data-cart-reject]');if(reject)ownerConfirm(reject.dataset.cartReject,false);const locate=e.target.closest('[data-use-dropoff]');if(locate)navigator.geolocation.getCurrentPosition(p=>{trackerLocation={lat:p.coords.latitude,lng:p.coords.longitude};document.querySelector('#dropoffLocationLabel').textContent=`Location set • ${trackerLocation.lat.toFixed(5)}, ${trackerLocation.lng.toFixed(5)}`},()=>showToast('Location permission was not granted','map-pin'));const accept=e.target.closest('[data-accept-bid]');if(accept)decideBid(accept.dataset.acceptBid,true);const decline=e.target.closest('[data-decline-bid]');if(decline)decideBid(decline.dataset.declineBid,false)});document.addEventListener('change',e=>{if(e.target.matches('[data-cart-unit]')){const item=cart.items[Number(e.target.dataset.cartUnit)];item.saleUnit=e.target.value;validate();renderCart()}});document.addEventListener('input',e=>{if(e.target.matches('[data-cart-qty]')){cart.items[Number(e.target.dataset.cartQty)].quantity=Math.max(1,Number(e.target.value)||1);validate();save();document.querySelector('#cartTotal').textContent=`US$ ${total().toFixed(2)}`}});document.addEventListener('submit',e=>{if(e.target.id==='cartCheckoutForm'){e.preventDefault();submitCheckout(e.target)}if(e.target.id==='orderLookupForm'){e.preventDefault();lookup(e.target)}if(e.target.id==='deliveryRequestForm'){e.preventDefault();requestDelivery(e.target)}})});
})();
